//! Platform-owned sender for transactional notification email.
//!
//! Notifications are generated by the platform, so they must leave through a
//! workspace/deployment sender (the native `secret/gbo/email` mailbox, or the
//! `MAIL_*` environment configuration). A user's connected Gmail/Outlook
//! mailbox is never a notification sender: its credentials are personal, may
//! be revoked at any time, and put delivery outside tenant control.
//!
//! When no platform sender is configured, delivery is disabled. Callers log
//! the reason instead of silently falling back to a user mailbox as the
//! sender. The *recipient* is still resolved from the mailbox the user
//! configured (#1853, [`notification_recipient`]).

use diesel::prelude::*;
use diesel::sql_types::Text;
use lettre::transport::smtp::authentication::Credentials;
use lettre::{Message, SmtpTransport, Transport};
use log::{debug, warn};

fn valid_address(value: &str) -> Option<String> {
    let value = value.trim();
    if value.is_empty() || value.eq_ignore_ascii_case("none") {
        return None;
    }
    value
        .parse::<lettre::address::Address>()
        .ok()
        .map(|_| value.to_string())
}

#[derive(QueryableByName)]
struct MailboxRow {
    #[diesel(sql_type = Text)]
    email: String,
}

/// Resolve the mailbox that receives a user's notification email.
///
/// #1853 — notifications belong in the mailbox the user configured, not
/// necessarily the login address. Precedence:
///   1. `notifications.email_recipient` (explicit choice in preferences);
///   2. the primary active mailbox from `user_email_accounts` (Mail app);
///   3. a linked Google/Microsoft account (`oauth_account_links`);
///   4. the profile address in `users.email`.
///
/// Only addresses that parse as an email are returned, so a malformed or
/// placeholder preference can never become an SMTP recipient.
pub(crate) fn notification_recipient(
    conn: &mut diesel::PgConnection,
    user_id: &str,
) -> Option<String> {
    let explicit = diesel::sql_query(
        "SELECT COALESCE(preference_value->>'email_recipient', '') AS email \
         FROM user_preferences \
         WHERE user_id::text = $1 AND preference_key = 'notifications' LIMIT 1",
    )
    .bind::<Text, _>(user_id)
    .get_result::<MailboxRow>(conn)
    .ok()
    .and_then(|row| valid_address(&row.email));
    if explicit.is_some() {
        return explicit;
    }

    let configured = diesel::sql_query(
        "SELECT email FROM user_email_accounts \
         WHERE user_id::text = $1 AND is_active \
         ORDER BY is_primary DESC, updated_at DESC LIMIT 1",
    )
    .bind::<Text, _>(user_id)
    .get_result::<MailboxRow>(conn)
    .ok()
    .and_then(|row| valid_address(&row.email));
    if configured.is_some() {
        return configured;
    }

    let linked = diesel::sql_query(
        "SELECT email FROM oauth_account_links \
         WHERE user_id::text = $1 \
           AND LOWER(provider) IN ('google', 'microsoft') \
           AND email IS NOT NULL AND email <> '' \
         ORDER BY updated_at DESC LIMIT 1",
    )
    .bind::<Text, _>(user_id)
    .get_result::<MailboxRow>(conn)
    .ok()
    .and_then(|row| valid_address(&row.email));
    if linked.is_some() {
        return linked;
    }

    let profile = diesel::sql_query("SELECT email FROM users WHERE id::text = $1 LIMIT 1")
        .bind::<Text, _>(user_id)
        .get_result::<MailboxRow>(conn)
        .ok()
        .and_then(|row| valid_address(&row.email));
    if profile.is_none() {
        debug!("notification email: no deliverable address for user {user_id}");
    }
    profile
}

pub(crate) struct NotificationSender {
    from: String,
    host: String,
    port: u16,
    username: String,
    password: String,
}

impl NotificationSender {
    /// Resolve the configured platform sender.
    ///
    /// Precedence: the deployment mailbox from Vault (`secret/gbo/email`, the
    /// same native sender used by Drive share-by-email) and then the `MAIL_*`
    /// / `SMTP_*` environment variables used by other platform mail paths.
    /// No user account is ever consulted.
    pub(crate) fn configured() -> Option<Self> {
        if let Ok(manager) = botcoresecrets::SecretsManager::get() {
            let (host, port, username, password, from) = manager.get_email_config();
            if let Some(sender) = Self::from_parts(&host, port, username, password, from) {
                return Some(sender);
            }
        }

        let host = env_first(&["MAIL_HOST", "SMTP_HOST", "EMAIL_SERVER"])?;
        let port = env_first(&["MAIL_PORT", "SMTP_PORT", "EMAIL_PORT"])
            .and_then(|value| value.parse().ok())
            .unwrap_or(587);
        let username = env_first(&["MAIL_USER", "SMTP_USER", "EMAIL_USER"]).unwrap_or_default();
        let password = env_first(&["MAIL_PASS", "SMTP_PASSWORD", "EMAIL_PASS"]).unwrap_or_default();
        let from = env_first(&["MAIL_FROM", "SMTP_FROM", "EMAIL_FROM"])?;

        Self::from_parts(&host, port, username, password, from)
    }

    fn from_parts(
        host: &str,
        port: u16,
        username: String,
        password: String,
        from: String,
    ) -> Option<Self> {
        let host = host.trim();
        let from = from.trim();
        if host.is_empty()
            || host.eq_ignore_ascii_case("none")
            || from.is_empty()
            || from.eq_ignore_ascii_case("none")
        {
            return None;
        }
        if from.parse::<lettre::address::Address>().is_err() {
            warn!("notification email: configured sender is not a valid address: {from}");
            return None;
        }
        Some(Self {
            from: from.to_string(),
            host: host.to_string(),
            port,
            username,
            password,
        })
    }

    pub(crate) fn send(&self, to: &str, subject: &str, body: &str) -> Result<(), String> {
        let message = Message::builder()
            .from(
                self.from
                    .parse()
                    .map_err(|e| format!("invalid sender address: {e}"))?,
            )
            .to(to.parse().map_err(|e| format!("invalid recipient: {e}"))?)
            .subject(subject)
            .body(body.to_string())
            .map_err(|e| format!("message build failed: {e}"))?;

        let local = self.host == "localhost"
            || self.host.starts_with("127.")
            || self.host == "::1"
            || self.host.ends_with(".local");
        let builder = if local {
            SmtpTransport::builder_dangerous(&self.host)
        } else {
            SmtpTransport::relay(&self.host).map_err(|e| format!("SMTP relay failed: {e}"))?
        };
        let mut builder = builder.port(self.port);
        if !self.username.is_empty() {
            builder = builder.credentials(Credentials::new(
                self.username.clone(),
                self.password.clone(),
            ));
        }
        builder
            .build()
            .send(&message)
            .map(|_| ())
            .map_err(|e| format!("SMTP send failed: {e}"))
    }
}

fn env_first(names: &[&str]) -> Option<String> {
    for name in names {
        if let Ok(value) = std::env::var(name) {
            let value = value.trim();
            if !value.is_empty() && !value.eq_ignore_ascii_case("none") {
                return Some(value.to_string());
            }
        }
    }
    None
}
